	private void assertNativeDirection(Association association) throws Exception {
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = strategy(dataset);
			TupleExpr root = root(association);
			List<BindingSet> expected = hand(association);
			List<BindingSet> generic = drain(strategy.genericOnlyView().precompile(root.clone()));
			assertThat(generic).as("independent full duplicate/UNDEF hand bag")
					.containsExactlyInAnyOrderElementsOf(expected);
			NativeRowsStep step = compile(root, strategy, dataset);
			assertThat(drain(step)).as("compiled native complete hand bag before shape or movement assertions")
					.containsExactlyInAnyOrderElementsOf(expected);
			assertThat(LmdbNativeInteriorPlans.hasAlternatives(step.arg)).isEqualTo(association.alternative());
			assertThat(step.consumerRequest != null).isEqualTo(association.alternative());
			List<BindingSet> nativeUnknown;
			try (Owned owned = new Owned(step)) {
				SlotPlan original = LmdbNativeInteriorPlans.lexical(step.arg);
				nativeUnknown = originalRows(step, owned.row(), original, false);
				List<BindingSet> nativeOrdered = originalRows(step, owned.row(), original, true);
				assertThat(nativeUnknown).containsExactlyInAnyOrderElementsOf(expected);
				assertThat(nativeOrdered).containsExactlyInAnyOrderElementsOf(expected);
				RowState row = owned.row();
				LmdbNativeInteriorPlans.Selection selected = LmdbNativeInteriorPlans.select(step.arg, row,
						step.consumerRequest);
				assertThat(LmdbNativeInteriorPlans.hasAlternatives(selected.plan)).isFalse();
				List<SlotPlan> originalBoundaries = new ArrayList<>();
				List<SlotPlan> selectedBoundaries = new ArrayList<>();
				boundaries(original, originalBoundaries);
				boundaries(selected.plan, selectedBoundaries);
				assertThat(selectedBoundaries).containsExactlyElementsOf(originalBoundaries);
				List<SlotPlan> originalPatterns = new ArrayList<>();
				patterns(original, originalPatterns);
				if (association.hasP()) {
					MultiJoinPlan core = core(selected.plan);
					assertThat(core.children).hasSize(originalPatterns.size());
					for (int index = 0; index < core.children.length; index++) {
						assertThat(core.children[index]).isSameAs(originalPatterns.get(index));
					}
				}
				long before = root.getLongMetricActual(OPTIMIZED);
				assertThat(drainSelected(step, row, selected, false)).containsExactlyInAnyOrderElementsOf(expected);
				assertThat(root.getLongMetricActual(OPTIMIZED) > before).isEqualTo(association.alternative());
				long opened = root.getLongMetricActual(OPTIMIZED);
				assertThat(drainSelected(step, owned.row(), selected, true)).containsExactlyElementsOf(nativeOrdered);
				assertThat(root.getLongMetricActual(OPTIMIZED)).isEqualTo(opened);
				RowState unknown = owned.row();
				LmdbNativeInteriorPlans.Selection plain = LmdbNativeInteriorPlans.select(step.arg, unknown, null);
				assertThat(plain.plan).isSameAs(original);
				assertThat(drainSelected(step, unknown, plain, false)).containsExactlyElementsOf(nativeUnknown);
				assertThat(root.getLongMetricActual(OPTIMIZED)).isEqualTo(opened);
			}
			TupleExpr fragment = root(association);
			assertThat(drain(strategy.precompile(fragment, context()))).containsExactlyElementsOf(nativeUnknown);
			assertThat(fragment.getLongMetricActual(OPTIMIZED)).isLessThanOrEqualTo(0L);
			if (association.hasP()) {
				assertPhysicalCore(step, expected, baseHand(association));
			}
		}
	}

