	private void assertSharedBoundaryDemands(TupleExpr root, List<BindingSet> single, boolean refusedExpansion)
			throws Exception {
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = strategy(dataset);
			List<BindingSet> expected = naturalJoin(single, single);
			assertThat(drain(strategy.genericOnlyView().precompile(root.clone())))
					.containsExactlyInAnyOrderElementsOf(single);
			NativeRowsStep step = compile(root, strategy, dataset);
			assertThat(drain(step)).containsExactlyInAnyOrderElementsOf(single);
			if (refusedExpansion) {
				assertThat(LmdbNativeInteriorPlans.carrier(step.arg)).isFalse();
				assertThat(LmdbNativeInteriorPlans.carrier(((JoinPlan) step.arg).left)).isTrue();
			}
			for (int mode = 0; mode < 6; mode++) {
				boolean reverse = mode >= 3;
				int demand = mode % 3;
				boolean mixed = demand != 0;
				TupleExpr otherExpr = mixed ? new Filter(root.clone(),
						new ValueConstant(repository.getValueFactory().createLiteral(true))) : root.clone();
				TupleExpr semantic = reverse ? new Join(otherExpr, root.clone()) : new Join(root.clone(), otherExpr);
				List<BindingSet> generic = drain(strategy.genericOnlyView().precompile(semantic.clone()));
				assertThat(generic).containsExactlyInAnyOrderElementsOf(expected);
				SlotPlan other = demand == 2 ? LmdbNativeInteriorPlans.lexical(step.arg) : step.arg;
				other = mixed ? new FilterPlan(other, row -> true, -1L) : other;
				SlotPlan shared = reverse ? new JoinPlan(other, step.arg) : new JoinPlan(step.arg, other);
				LmdbNativeInteriorPlans.Request request = LmdbNativeInteriorPlans.request(shared, step.source,
						step.layout, NativeTupleFacts.of(semantic));
				try (Owned owned = new Owned(step)) {
					SlotPlan original = LmdbNativeInteriorPlans.lexical(step.arg);
					SlotPlan originalOther = original;
					if (mixed) {
						FilterPlan filter = (FilterPlan) other;
						originalOther = new FilterPlan(original, filter.filter, filter.filterMask, filter.termKindFilter);
					}
					SlotPlan originalShared = reverse
							? new JoinPlan(originalOther, original) : new JoinPlan(original, originalOther);
					List<BindingSet> nativeUnknown = originalRows(step, owned.row(), originalShared, false);
					List<BindingSet> nativeOrdered = originalRows(step, owned.row(), originalShared, true);
					assertThat(nativeUnknown).containsExactlyInAnyOrderElementsOf(expected);
					assertThat(nativeOrdered).containsExactlyInAnyOrderElementsOf(expected);
					RowState row = owned.row();
					LmdbNativeInteriorPlans.Selection selected = LmdbNativeInteriorPlans.select(shared, row, request);
					assertThat(selected.plan).isInstanceOf(JoinPlan.class);
					JoinPlan graph = (JoinPlan) selected.plan;
					SlotPlan plain = reverse ? graph.right : graph.left;
					SlotPlan otherSelected = reverse ? graph.left : graph.right;
					SlotPlan otherInput = mixed ? ((FilterPlan) otherSelected).arg : otherSelected;
					if (refusedExpansion && demand == 2) {
						assertSameLexicalOperands(plain, original);
						assertSameLexicalOperands(otherInput, original);
					} else {
						assertThat(otherInput).isSameAs(plain);
					}
					assertThat(LmdbNativeInteriorPlans.hasAlternatives(selected.plan)).isFalse();
					long before = root.getLongMetricActual(OPTIMIZED);
					List<BindingSet> actual = drainSelected(step, row, selected, false);
					assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
					assertThat(LmdbNativeInteriorPlans.hasAlternatives(step.arg)).isTrue();
					assertThat(request).isNotNull();
					if (mixed) {
						assertThat(actual).containsExactlyElementsOf(nativeUnknown);
					}
					assertThat(root.getLongMetricActual(OPTIMIZED) > before).isEqualTo(!mixed);
					long opened = root.getLongMetricActual(OPTIMIZED);
					assertThat(drainSelected(step, owned.row(), selected, true)).containsExactlyElementsOf(nativeOrdered);
					assertThat(root.getLongMetricActual(OPTIMIZED)).isEqualTo(opened);
					RowState unknown = owned.row();
					LmdbNativeInteriorPlans.Selection unknownInput = LmdbNativeInteriorPlans.select(shared, unknown, null);
					assertThat(drainSelected(step, unknown, unknownInput, false)).containsExactlyElementsOf(nativeUnknown);
					assertThat(root.getLongMetricActual(OPTIMIZED)).isEqualTo(opened);
				}
			}
		}
	}

	/** Separate normalized join wrappers retain the same original opaque, native-core and filter operands. */
	private static void assertSameLexicalOperands(SlotPlan actual, SlotPlan original) {
		if (original instanceof JoinPlan join) {
			assertThat(actual).isInstanceOf(JoinPlan.class);
			JoinPlan selected = (JoinPlan) actual;
			assertSameLexicalOperands(selected.left, join.left);
			assertSameLexicalOperands(selected.right, join.right);
		} else {
			assertThat(actual).isSameAs(original);
		}
	}

