			NativeRowsStep step = compile(root, strategy, dataset);
			assertThat(LmdbNativeInteriorPlans.hasAlternatives(step.arg)).isFalse();
			assertThat(step.consumerRequest).isNull();
			assertThat(firstBoundary(step.arg).hoistableAcross(Set.of())).isFalse();
			Value first = assertVolatileBag(drain(step));
			Value second = assertVolatileBag(drain(step));
			assertThat(second).isNotEqualTo(first);
